        | CSSNumericValueOrDOMStringOrCSSOMKeywordValue.DOMString value -> box value
        | CSSNumericValueOrDOMStringOrCSSOMKeywordValue.CSSOMKeywordValue value ->
            if isNull (box value) then
                nullArg "value"

